from collections import deque, defaultdict

def components(arr, color, r0=0,r1=None,c0=0,c1=None, conn=4):
    if r1 is None:r1=len(arr)
    if c1 is None:c1=len(arr[0])
    dirs=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
    seen=set(); out=[]
    for r in range(r0,r1):
      for c in range(c0,c1):
        if arr[r][c]!=color or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        for x,y in q:
          cells.append((x,y))
          for dr,dc in dirs:
            p=(x+dr,y+dc)
            if r0<=p[0]<r1 and c0<=p[1]<c1 and p not in seen and arr[p[0]][p[1]]==color:
              seen.add(p);q.append(p)
        out.append(cells)
    return out

def mask(cells):
    rmin=min(r for r,c in cells);rmax=max(r for r,c in cells);cmin=min(c for r,c in cells);cmax=max(c for r,c in cells)
    return '\n'.join(''.join('#' if (r,c) in set(cells) else '.' for c in range(cmin,cmax+1)) for r in range(rmin,rmax+1))

