def normalize_shape(cells):
    # canonical among rotations and reflections
    pts=[(r-min(x for x,y in cells), c-min(y for x,y in cells)) for r,c in cells]
    variants=[]
    for refl in [1,-1]:
      cur=[(r,c*refl) for r,c in pts]
      for _ in range(4):
        minr=min(r for r,c in cur); minc=min(c for r,c in cur)
        norm=tuple(sorted((r-minr,c-minc) for r,c in cur))
        variants.append(norm)
        cur=[(c,-r) for r,c in cur]
    return min(variants)

